const r = await tools.exec_command({cmd:"python - <<'PY'
from PIL import Image,ImageDraw
from scipy.ndimage import distance_transform_edt, map_coordinates, gaussian_filter1d
import numpy as np
im=Image.open('/app/target.png').convert('RGB'); m=np.array(Image.open('/app/target.png').convert('L'))<128; D=distance_transform_edt(m)
paths=[[(493,272),(512,297),(514,320),(508,350),(494,385),(478,420),(466,450),(449,480),(426,520),(396,560),(360,600),(319,640),(267,680),(220,709)],[(480,450),(515,495),(550,540),(590,585),(630,625),(670,660),(710,680),(750,693),(790,702),(815,708),(829,710)]]
def catmull(P,n=30):
 P=np.array(P,float); out=[]
 for i in range(len(P)-1):
  p0=P[max(0,i-1)]; p1=P[i]; p2=P[i+1]; p3=P[min(len(P)-1,i+2)]
  for t in np.linspace(0,1,n,endpoint=False):
   t2=t*t;t3=t2*t
   out.append(.5*((2*p1)+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t2+(-p0+3*p1-3*p2+p3)*t3))
 out.append(P[-1]); return np.array(out)
def arc_resample(P,step=10.0):
 ds=np.linalg.norm(np.diff(P,axis=0),axis=1); s=np.r_[0,np.cumsum(ds)]; sn=np.arange(0,s[-1],step); sn=np.r_[sn,s[-1]]
 return np.column_stack([np.interp(sn,s,P[:,j]) for j in range(2)])
d=ImageDraw.Draw(im)
for ix,anchors in enumerate(paths):
 curve=catmull(anchors); pts=arc_resample(curve,step=10)
 vals=map_coordinates(D,[pts[:,1],pts[:,0]],order=1,mode='nearest')
 widths=2*vals*.22186
 widths=gaussian_filter1d(widths,1.3)
 print('stroke',ix,'n',len(pts),'length mm',sum(np.linalg.norm(np.diff(pts,axis=0),axis=1))*.22186)
 for i in range(0,len(pts),max(1,len(pts)//10)):
  print(' ',np.round(pts[i],1).tolist(),'width',round(widths[i],1),'press',round(widths[i],1))
 for a,b in zip(pts[:-1],pts[1:]): d.line([tuple(a),tuple(b)],fill=(255,0,0),width=3)
 for u,v in pts[::max(1,len(pts)//12)]: d.ellipse((u-3,v-3,u+3,v+3),fill=(0,180,255))
im.save('/app/output/target_path_preview.png')
PY"});
